#!/usr/bin/env bash\n# post_zen_comment.sh - selects a random Zen quote and posts it as a PR comment.\n\nset -euo pipefail\n\n# List of Zen quotes\nquotes=(\n"Peace comes from within. Do not seek it elsewhere."\n"The journey of a thousand miles begins with a single step."\n"Silence is a source of great strength."\n"Let go or be dragged."\n"The obstacle is the path."\n)\n\n# Choose a random quote\nRANDOM_INDEX=$((RANDOM % ${#quotes[@]}))\nquote="${quotes[$RANDOM_INDEX]}"\n\n# Build API URL\napi_url="https://api.github.com/repos/${GITHUB_REPOSITORY}/issues/${PR_NUMBER}/comments"\n\n# Prepare JSON payload\npayload=$(printf '{"body":"%s"}' "$quote")\n\n# Use curl (or mock via CURL_CMD env) to post comment\nCURL_CMD="${CURL_CMD:-curl}"\n$CURL_CMD -s -X POST \\\n  -H "Authorization: token ${GITHUB_TOKEN}" \\\n  -H "Accept: application/vnd.github.v3+json" \\\n  -d "$payload" \\\n  "$api_url"
